export function createResilientFetch({
  fetch,
  sleep,
  random = Math.random,
  maxAttempts = 4,
  baseDelayMs = 200,
  maxDelayMs = 5000,
}) {
  const retryableStatuses = new Set([408, 429, 500, 502, 503, 504]);
  const retryableMethods = new Set(["GET", "HEAD", "OPTIONS", "PUT", "DELETE"]);

  function canRetry(options) {
    const method = String(options.method ?? "GET").toUpperCase();

    if (retryableMethods.has(method)) return true;
    if (method !== "POST" && method !== "PATCH") return false;

    const headers = options.headers;
    if (headers == null) return false;

    if (typeof headers.has === "function") {
      return headers.has("Idempotency-Key");
    }
    if (typeof headers.get === "function") {
      return headers.get("Idempotency-Key") != null;
    }

    return Object.keys(headers).some(
      (name) => name.toLowerCase() === "idempotency-key"
    );
  }

  function jitterDelay(retryNumber) {
    return Math.floor(
      random() *
        Math.min(maxDelayMs, baseDelayMs * 2 ** (retryNumber - 1))
    );
  }

  return async function rfetch(url, options = {}) {
    for (let attempt = 1; ; attempt += 1) {
      if (options.signal?.aborted) {
        const error = new Error("The operation was aborted.");
        error.name = "AbortError";
        throw error;
      }

      let response;
      try {
        response = await fetch(url, options);
      } catch (error) {
        if (
          error?.name === "AbortError" ||
          attempt >= maxAttempts ||
          !canRetry(options)
        ) {
          throw error;
        }

        await sleep(jitterDelay(attempt), options.signal);
        continue;
      }

      if (
        response.ok === true ||
        !retryableStatuses.has(response.status) ||
        attempt >= maxAttempts ||
        !canRetry(options)
      ) {
        return response;
      }

      const retryAfter = response.headers.get("Retry-After");
      let delayMs;

      if (
        typeof retryAfter === "string" &&
        retryAfter.length > 0 &&
        !/[^0-9]/.test(retryAfter)
      ) {
        delayMs = Number(retryAfter) * 1000;
        if (delayMs > maxDelayMs) {
          return response;
        }
      } else {
        delayMs = jitterDelay(attempt);
      }

      await sleep(delayMs, options.signal);
    }
  };
}
